-- Private, opt-in personalization. No executable CSS, shared profile skins or auth modifications.
BEGIN;
CREATE TABLE public.global_personalization_preferences(user_id uuid PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,settings jsonb NOT NULL,themes jsonb NOT NULL,revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.global_personalization_operations(user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,operation_id uuid NOT NULL,fingerprint text NOT NULL,revision bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,operation_id));
CREATE INDEX personalization_operations_rate ON public.global_personalization_operations(user_id,created_at DESC);
ALTER TABLE public.global_personalization_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.global_personalization_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.global_personalization_preferences,public.global_personalization_operations FROM PUBLIC,anon,authenticated;
CREATE POLICY preferences_owner ON public.global_personalization_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY operations_owner ON public.global_personalization_operations FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.personalization_keys(v jsonb,keys text[]) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE WHEN jsonb_typeof(v)='object' THEN COALESCE((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v)k)=(SELECT array_agg(k ORDER BY k) FROM unnest(keys)k),false) ELSE false END; $$;
CREATE FUNCTION public.personalization_luminance(hex text) RETURNS double precision LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT sum(weight*CASE WHEN channel<=0.04045 THEN channel/12.92 ELSE power((channel+0.055)/1.055,2.4) END) FROM(SELECT get_byte(decode(substr(hex,2),'hex'),i)/255.0 AS channel,(ARRAY[0.2126,0.7152,0.0722])[i+1] AS weight FROM generate_series(0,2)i)c;
$$;
CREATE FUNCTION public.personalization_ratio(a text,b text) RETURNS double precision LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT (GREATEST(public.personalization_luminance(a),public.personalization_luminance(b))+0.05)/(LEAST(public.personalization_luminance(a),public.personalization_luminance(b))+0.05); $$;
CREATE FUNCTION public.personalization_theme_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE k text;bg text;r record;BEGIN
 IF v IS NULL OR octet_length(v::text)>8000 OR NOT public.personalization_keys(v,ARRAY['colors','typography','components','effects']) THEN RETURN false;END IF;
 IF NOT public.personalization_keys(v->'colors',ARRAY['bg','surface','elevated','text','muted','link','button','buttonText','border','accent','focus','success','warning','error']) OR NOT public.personalization_keys(v->'typography',ARRAY['font','size','lineHeight','headingWeight','letterSpacing']) OR NOT public.personalization_keys(v->'components',ARRAY['cardRadius','buttonRadius','borderWidth','shadow','spacing','density']) OR NOT public.personalization_keys(v->'effects',ARRAY['mode','intensity','speed','saturation','targets']) THEN RETURN false;END IF;
 FOR r IN SELECT * FROM jsonb_each(v->'colors') LOOP IF jsonb_typeof(r.value)<>'string' OR r.value#>>'{}' !~ '^#[a-fA-F0-9]{6}$' THEN RETURN false;END IF;END LOOP;
 FOREACH bg IN ARRAY ARRAY['bg','surface','elevated'] LOOP
  FOREACH k IN ARRAY ARRAY['text','muted','link','success','warning','error'] LOOP IF public.personalization_ratio(v->'colors'->>k,v->'colors'->>bg)<4.5 THEN RETURN false;END IF;END LOOP;
  FOREACH k IN ARRAY ARRAY['focus','border'] LOOP IF public.personalization_ratio(v->'colors'->>k,v->'colors'->>bg)<3 THEN RETURN false;END IF;END LOOP;
 END LOOP;
 IF public.personalization_ratio(v->'colors'->>'buttonText',v->'colors'->>'button')<4.5 THEN RETURN false;END IF;
 FOR r IN SELECT * FROM(VALUES('typography','size',14.,22.),('typography','lineHeight',1.4,1.9),('typography','headingWeight',500.,800.),('typography','letterSpacing',0.,0.12),('components','cardRadius',0.,24.),('components','buttonRadius',0.,24.),('components','borderWidth',1.,3.),('components','spacing',0.85,1.3),('effects','intensity',0.,0.4),('effects','speed',10.,90.),('effects','saturation',0.,1.))bounds(g,k,lo,hi) LOOP IF jsonb_typeof(v->r.g->r.k) IS DISTINCT FROM 'number' OR (v->r.g->>r.k)::numeric NOT BETWEEN r.lo AND r.hi THEN RETURN false;END IF;END LOOP;
 IF jsonb_typeof(v->'typography'->'font') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'components'->'shadow') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'components'->'density') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'effects'->'mode') IS DISTINCT FROM 'string' OR v->'typography'->>'font' NOT IN ('sans','serif','mono') OR v->'components'->>'shadow' NOT IN ('none','soft','deep') OR v->'components'->>'density' NOT IN ('compact','normal','comfortable') OR v->'effects'->>'mode' NOT IN ('off','static','soft','dynamic') THEN RETURN false;END IF;
 IF jsonb_typeof(v->'effects'->'targets') IS DISTINCT FROM 'array' OR jsonb_array_length(v->'effects'->'targets')>4 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'effects'->'targets')x WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' NOT IN ('borders','icons','highlights','decoration')) OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(v->'effects'->'targets')x) THEN RETURN false;END IF;
 RETURN true;EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION public.global_personalization(p_action text,p_payload jsonb DEFAULT NULL,p_revision bigint DEFAULT NULL,p_operation uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid();stored public.global_personalization_preferences%ROWTYPE;receipt public.global_personalization_operations%ROWTYPE;fp text;s jsonb;t jsonb;r jsonb;ids uuid[];theme_id text;BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501';END IF;
 IF p_action='read' THEN SELECT * INTO stored FROM public.global_personalization_preferences WHERE user_id=actor;RETURN jsonb_build_object('settings',stored.settings,'themes',COALESCE(stored.themes,'[]'),'revision',COALESCE(stored.revision,0));END IF;
 IF p_action IS DISTINCT FROM 'save' OR p_operation IS NULL OR p_revision IS NULL OR p_revision<0 OR p_payload IS NULL OR octet_length(p_payload::text)>200000 OR NOT public.personalization_keys(p_payload,ARRAY['settings','themes']) THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('personalization:'||actor::text,0));fp:=encode(sha256(convert_to(jsonb_build_array(p_payload,p_revision)::text,'UTF8')),'hex');
 SELECT * INTO receipt FROM public.global_personalization_operations WHERE user_id=actor AND operation_id=p_operation;
 IF FOUND THEN IF receipt.fingerprint<>fp THEN RAISE EXCEPTION 'Operation reused' USING ERRCODE='22023';END IF;RETURN p_payload||jsonb_build_object('revision',receipt.revision);END IF;
 IF(SELECT count(*) FROM public.global_personalization_operations WHERE user_id=actor AND created_at>now()-interval '1 minute')>=30 THEN RAISE EXCEPTION 'Rate limited' USING ERRCODE='54000';END IF;
 SELECT * INTO stored FROM public.global_personalization_preferences WHERE user_id=actor FOR UPDATE;
 IF COALESCE(stored.revision,0)<>p_revision THEN RAISE EXCEPTION 'Preference conflict' USING ERRCODE='40001';END IF;
 s:=p_payload->'settings';t:=p_payload->'themes';
 IF NOT public.personalization_keys(s,ARRAY['theme','config','region','locale','readingLanguages']) OR NOT public.personalization_theme_valid(s->'config') OR s->>'locale' IS DISTINCT FROM 'pt-PT' OR jsonb_typeof(s->'theme') IS DISTINCT FROM 'string' OR jsonb_typeof(t) IS DISTINCT FROM 'array' OR jsonb_array_length(t)>20 THEN RAISE EXCEPTION 'Invalid preferences' USING ERRCODE='22023';END IF;
 IF s->'region'<>'null'::jsonb AND (jsonb_typeof(s->'region')<>'string' OR NOT(s->>'region'=ANY(ARRAY['AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW']))) THEN RAISE EXCEPTION 'Invalid region' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(s->'readingLanguages') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'readingLanguages')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'readingLanguages')l WHERE jsonb_typeof(l)<>'string' OR NOT(l#>>'{}'=ANY(ARRAY['aa','ab','abq','abq-Latn','abr','ace','ach','acr','ada','ady','aeb','af','agq','agu','ak','alt','am','amo','an','ann','aoa','aoz','apc','apd','ar','arn','aro','arq','ars','ary','arz','as','asa','ast','atj','av','awa','ay','az','az-Arab','az-Cyrl','ba','bal','ban','ban-Bali','bap','bar','bas','bax','bbc','bbj','bci','be','bej','bem','bew','bez','bfd','bfq','bft','bfy','bg','bgc','bgn','bgx','bhb','bhi','bho','bi','bik','bin','bjj','bjn','bjt','bkm','bku','bla','blo','blt','bm','bm-Nkoo','bmq','bn','bo','bpy','bqi','bqv','br','bra','brh','brx','bs','bs-Cyrl','bsc','bsq','bss','bto','btv','bua','buc','bug','bum','bvb','byn','byv','bza','bze','bzj','ca','caa','cab','cac','cad','cak','cce','cch','ccp','ccr','ce','ceb','cgg','ch','chk','chm','cho','chp','chr','chw','cic','cja','cjk','cjm','ckb','ckz','clc','co','cop','cps','cr','crg','crh','cri','crk','crl','crs','cs','csb','csw','cu','cv','cy','da','dak','dar','dav','dcc','de','den','dgr','dje','dnj','doi','dsb','dtm','dtp','dty','dua','dv','dyo','dyu','dz','ebu','ecy','ee','efi','egl','el','en','en-Shaw','eo','es','esu','et','eu','ewo','ext','fa','fan','fbl','ff','ff-Adlm','ffm','fi','fia','fil','fit','fj','fji','fo','fon','fr','frc','frp','frr','frs','fud','fuq','fur','fuv','fvr','fy','ga','gaa','gag','gan','gay','gbm','gbz','gcr','gd','gez','gil','gjk','gju','gl','glk','gmy','gn','gon','gor','gos','grb','grc','grr','grt','gsw','gu','gub','guc','gur','guz','gv','gvr','gwi','ha','ha-Arab','hak','hak-Hant','haw','haz','he','hi','hi-Latn','hif','hil','hnd','hne','hnj','hnn','hno','ho','hoc','hoj','hr','hsb','hsn','ht','hu','hur','hy','hz','ia','iba','ibb','id','ie','ife','ig','ii','ik','ilo','inh','io','is','it','itz','iu','iu-Latn','ixl','izh','ja','jac','jam','jbo','jgo','jmc','jml','jut','jv','ka','kaa','kab','kac','kaj','kam','kao','kaw','kbd','kcg','kck','kde','kdt','kea','kek','ken','kfo','kfr','kfy','kg','kge','kgp','kha','khb','khn','khq','kht','khw','ki','kiu','kj','kjb','kjg','kk','kk-Arab','kkj','kl','kln','km','kmb','kmr','kn','knf','knj','knn','ko','koi','kok','kos','kpe','kqn','krc','kri','krj','krl','kro','kru','ks','ksb','ksf','ksh','kss','ku','ku-Arab','ku-Cyrl','kua','kum','kv','kvr','kvx','kw','kwk','kxm','kxp','kxv','ky','ky-Arab','ky-Latn','la','lad','lag','lah','laj','lb','lbe','lbw','lcp','leb','len','lep','lez','lg','li','lif','lij','lil','lir','lis','ljp','lki','lkt','lld','lmn','lmo','ln','lo','lol','loz','lrc','lt','ltg','lu','lua','lue','lun','luo','luy','luz','lv','lwl','lzh','lzz','lzz-Geor','mad','maf','mag','mai','mak','mam','man','man-Nkoo','mas','maz','mdf','mdh','mdr','men','mer','mev','mey','mey-Latn','mfa','mfe','mfv','mg','mgh','mgo','mgp','mgy','mh','mhn','mi','mic','min','mix','mk','ml','mls','mn','mn-Mong','mni','mnw','moe','moh','mop','mos','mr','mrd','mrj','mro','ms','ms-Arab','mt','mtr','mua','mul','mus','mvy','mwk','mwl','mwr','mwv','mww','mxc','my','myv','myx','mzb','mzn','na','nah','nan','nan-Hant','nap','naq','nb','nch','nd','ndc','nds','ne','new','ng','ngl','nhe','nhw','nij','niu','njo','nl','nmg','nn','nnh','no','nod','noe','nqo','nr','nse','nsk','nso','nus','nv','nxq','ny','nym','nyn','nyu','nzi','oc','oj','ojs','ojw','oka','om','or','os','osa','pa','pa-Arab','pag','pam','pap','pau','pcd','pcm','pdc','pdt','pfl','pi','pi-Deva','pi-Mymr','pi-Sinh','pi-Thai','pis','pko','pl','pms','pnt','pnt-Cyrl','pnt-Latn','poc','poh','pon','pov','ppl','pqm','prd','pre','prg','ps','pt','pt-BR','pt-MZ','pt-PT','puu','qu','quc','qug','qum','quv','raj','rcf','rej','rgn','rhg','ria','rif','rif-Tfng','rjs','rkt','rm','rmf','rmo','rmt','rmu','rn','rng','ro','rob','rof','rtm','ru','rue','rug','rw','rwk','ryu','sa','saf','sah','saq','sas','sat','sav','saz','sbp','sc','sck','scn','sco','sd','sd-Deva','sdc','sdh','se','sef','seh','sei','ses','sg','sgs','shi','shi-Latn','shn','si','sid','sk','skr','sl','sli','sly','sm','sma','smj','smn','sms','sn','snf','snk','so','sou','sq','sr','sr-Latn','srn','srr','srx','ss','ssy','st','stq','stu','stu-Tale','su','suk','sus','suz','sv','sw','swb','swg','swv','sxn','syl','syr','szl','ta','taj','tbw','tcy','tdd','tdg','tdh','te','tem','teo','tet','tg','tg-Arab','th','thl','thq','thr','ti','tig','tiv','tk','tkl','tkr','tkt','tl','tly','tmh','tn','tnr','to','tog','toi','tpi','tr','tru','trv','trw','ts','tsc','tsd','tsg','tsj','tt','ttc','ttj','tts','ttt','tum','tvl','twq','ty','tyv','tzj','tzm','udm','ug','ug-Cyrl','uk','uli','umb','und','unr','unr-Deva','unx','ur','usp','uz','uz-Arab','uz-Cyrl','vai','vai-Latn','ve','vec','vep','vi','vic','vls','vmf','vmw','vot','vro','vun','wa','wae','wal','war','wbp','wbq','wbr','wls','wni','wo','wtm','wuu','xav','xh','xin','xmf','xnr','xog','xsm','xsr','yao','yap','yav','ybb','yi','yo','yrl','yua','yue','yue-Hans','za','zag','zap','zdj','zea','zgh','zh','zh-Hant','zmi','zu','zxx','zza']))) OR (SELECT count(*)<>count(DISTINCT l) FROM jsonb_array_elements(s->'readingLanguages')l) THEN RAISE EXCEPTION 'Invalid reading languages' USING ERRCODE='22023';END IF;
 FOR r IN SELECT * FROM jsonb_array_elements(t) LOOP
  IF NOT public.personalization_keys(r,ARRAY['id','name','config']) OR jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR r->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR jsonb_typeof(r->'name') IS DISTINCT FROM 'string' OR char_length(btrim(r->>'name')) NOT BETWEEN 1 AND 80 OR NOT public.personalization_theme_valid(r->'config') THEN RAISE EXCEPTION 'Invalid personal theme' USING ERRCODE='22023';END IF;
  IF (r->>'id')::uuid=ANY(COALESCE(ids,'{}')) THEN RAISE EXCEPTION 'Duplicate theme' USING ERRCODE='22023';END IF;ids:=array_append(ids,(r->>'id')::uuid);
 END LOOP;
 theme_id:=s->>'theme';IF theme_id NOT IN ('night','ruby','sunset','gold','emerald','ocean','sapphire','amethyst','sakura','parchment','minimal','contrast','light','dark','system','custom') THEN
  IF theme_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR NOT(theme_id::uuid=ANY(COALESCE(ids,'{}'))) THEN RAISE EXCEPTION 'Theme owner required' USING ERRCODE='42501';END IF;
 END IF;
 INSERT INTO public.global_personalization_preferences(user_id,settings,themes) VALUES(actor,s,t) ON CONFLICT(user_id) DO UPDATE SET settings=EXCLUDED.settings,themes=EXCLUDED.themes,revision=global_personalization_preferences.revision+1,updated_at=now() RETURNING * INTO stored;
 INSERT INTO public.global_personalization_operations(user_id,operation_id,fingerprint,revision) VALUES(actor,p_operation,fp,stored.revision);
 RETURN jsonb_build_object('settings',stored.settings,'themes',stored.themes,'revision',stored.revision);
END $$;
REVOKE ALL ON FUNCTION public.personalization_keys(jsonb,text[]),public.personalization_luminance(text),public.personalization_ratio(text,text),public.personalization_theme_valid(jsonb),public.global_personalization(text,jsonb,bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.global_personalization(text,jsonb,bigint,uuid) TO authenticated;
COMMIT;
